META TAG CSP (para HTML standalone):
<meta http-equiv="Content-Security-Policy" content="
    default-src 'self';
    script-src 'self' https://cdn.jsdelivr.net/npm/mermaid@10.6.1/;
    style-src 'self' 'unsafe-inline';
    img-src 'self' data:;
    font-src 'self';
    connect-src 'self';
    frame-ancestors 'none';
    base-uri 'self';
    form-action 'self';
">

HEADER HTTP (para servidor web):
Content-Security-Policy: default-src 'self'; script-src 'self' https://cdn.jsdelivr.net; ...

EXPLICAÇÃO DAS DIRETIVAS:
- default-src 'self': Apenas recursos do mesmo domínio
- script-src: Scripts apenas de 'self' + CDN Mermaid específico
- style-src 'unsafe-inline': Permite CSS inline (necessário para estilos embutidos)
- frame-ancestors 'none': Previne clickjacking
- base-uri 'self': Previne ataques via <base> tag

FASTAPI ENDPOINT:

```python
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
import yaml

app = FastAPI(title="MPGO Process Mapper API", version="3.1.0")

class ProcessRequest(BaseModel):
    nome: str
    descricao: str
    etapas: list[dict]
    formato_saida: str = "markdown"  # markdown|html|json

class ProcessResponse(BaseModel):
    status: str
    artefatos: dict
    metricas: dict

@app.post("/api/v1/generate", response_model=ProcessResponse)
async def gerar_processo(request: ProcessRequest):
    try:
        # Validar input
        if len(request.etapas) < 2:
            raise HTTPException(400, "Mínimo 2 etapas necessárias")

        # Gerar artefatos
        engine = ProcessEngine()
        resultado = engine.gerar(
            nome=request.nome,
            descricao=request.descricao,
            etapas=request.etapas
        )

        # Calcular métricas
        metricas = engine.calcular_metricas(resultado)

        # Verificar threshold
        if metricas['score_global'] < 85:
            raise HTTPException(422, "Qualidade abaixo do threshold")

        # Formatar output
        if request.formato_saida == "markdown":
            output = resultado['documentacao_md']
        elif request.formato_saida == "html":
            output = resultado['html_completo']
        else:
            output = resultado

        return ProcessResponse(
            status="success",
            artefatos={
                "documentacao": output,
                "mermaid": resultado['codigo_mermaid'],
                "versao": "3.1.0"
            },
            metricas=metricas
        )

    except Exception as e:
        raise HTTPException(500, str(e))

@app.get("/api/v1/health")
async def health():
    return {"status": "healthy", "version": "3.1.0"}
```

